:root {
  --smog:#2a2620; --smog-dark:#1a1814; --ink:#f0e8d8;
  --ink-dim:#b8a888; --ink-faint:#6a5e50;
  --rust:#c85a2a; --rust-light:#e87a4a;
  --gold:#e8b030; --gold-dim:#9a7020;
  --green:#5acc2a; --blue:#4a8ae8;
  --red:#e83a2a; --purple:#9a4ae8;
}
*{margin:0;padding:0;box-sizing:border-box;}
@page { margin: 0; size: auto; }
@media print {
  body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .page { page-break-inside: avoid; }
}
body{background:var(--smog-dark);color:var(--ink);font-family:'Libre Baskerville',serif;}
.page{max-width:960px;margin:0 auto;padding:48px 40px;border-left:1px solid rgba(120,100,70,0.2);border-right:1px solid rgba(120,100,70,0.2);}
.page+.page{border-top:1px solid rgba(120,100,70,0.15);}
.beast-number{font-family:'IBM Plex Mono',monospace;font-size:9px;letter-spacing:0.3em;color:var(--green);text-transform:uppercase;margin-bottom:6px;}
.beast-name{font-family:'IM Fell English',serif;font-size:32px;color:var(--ink);margin-bottom:4px;line-height:1.2;}
.beast-epithet{font-family:'IM Fell English',serif;font-style:italic;font-size:12px;color:var(--ink-dim);margin-bottom:32px;}
.beast-illustration{width:100%;margin-bottom:36px;border:1px solid rgba(120,100,60,0.3);background:var(--smog-dark);}
svg.beast-svg{width:100%;display:block;}
.beast-body{display:grid;grid-template-columns:1fr 220px;gap:28px;margin-top:28px;}
.workflow-title{font-family:'IBM Plex Mono',monospace;font-size:9px;letter-spacing:0.25em;color:var(--green);text-transform:uppercase;margin-bottom:14px;padding-bottom:7px;border-bottom:1px solid rgba(90,204,42,0.3);}
.workflow-steps{list-style:none;counter-reset:step;}
.workflow-steps li{counter-increment:step;display:flex;gap:10px;align-items:flex-start;padding:14px 0;border-bottom:1px solid rgba(120,100,70,0.1);font-size:12px;color:var(--ink-dim);line-height:1.5;}
.workflow-steps li::before{content:counter(step,decimal-leading-zero);font-family:'IBM Plex Mono',monospace;font-size:10px;color:var(--rust);min-width:26px;padding-top:1px;}
.workflow-steps li strong{color:var(--ink);font-weight:700;display:block;margin-bottom:2px;font-size:13px;}
.workflow-steps li .doctrine-tag{font-family:'IBM Plex Mono',monospace;font-size:9px;color:var(--gold-dim);display:block;margin-top:2px;font-style:italic;}
.margin-col{border-left:1px solid rgba(120,100,70,0.2);padding-left:18px;}
.doctrine-label{font-family:'IBM Plex Mono',monospace;font-size:9px;letter-spacing:0.2em;color:var(--green);text-transform:uppercase;margin-bottom:3px;}
.doctrine-name{font-family:'IM Fell English',serif;font-size:12px;color:var(--gold-dim);margin-bottom:3px;line-height:1.4;}
.doctrine-stated{font-size:9px;color:var(--ink-faint);font-style:italic;line-height:1.5;margin-bottom:3px;}
.doctrine-actual{font-size:9px;color:var(--rust-light);line-height:1.5;}
.doctrine-entry{margin-bottom:24px;}
.doctrine-divider{width:100%;height:1px;background:rgba(120,100,70,0.15);margin:18px 0;}
.cover{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;min-height:60vh;padding:60px 40px;}
.cover-latin{font-family:'IM Fell English',serif;font-style:italic;font-size:44px;color:var(--ink);margin-bottom:8px;}
.cover-sub{font-family:'IM Fell English',serif;font-style:italic;font-size:16px;color:var(--ink-dim);margin-bottom:32px;}
.cover-rule{width:180px;height:1px;background:linear-gradient(to right,transparent,var(--gold-dim),transparent);margin:16px auto;}
.cover-org{font-family:'IBM Plex Mono',monospace;font-size:9px;letter-spacing:0.3em;color:var(--ink-faint);text-transform:uppercase;margin-bottom:40px;}
.cover-url{font-family:'IBM Plex Mono',monospace;font-size:9px;color:var(--ink-faint);letter-spacing:0.2em;margin-top:32px;}
.survivor-block{border-left:3px solid var(--rust);padding:24px 28px;margin:40px 0;}
.survivor-text{font-family:'IM Fell English',serif;font-size:22px;font-style:italic;color:var(--ink);line-height:1.7;margin-bottom:14px;}
.survivor-attr{font-family:'IBM Plex Mono',monospace;font-size:9px;color:var(--ink-faint);letter-spacing:0.15em;text-transform:uppercase;}
.poem-page{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:80vh;text-align:center;}
.poem-stanza{font-family:'IM Fell English',serif;font-size:17px;color:var(--ink);line-height:1.9;margin-bottom:28px;font-style:italic;}
.poem-title{font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:0.25em;color:var(--ink-faint);text-transform:uppercase;margin-bottom:36px;}
.poem-rule{width:100px;height:1px;background:linear-gradient(to right,transparent,var(--ink-faint),transparent);margin:16px auto 28px;}
.poem-dedication{font-family:'IBM Plex Mono',monospace;font-size:9px;color:var(--ink-faint);letter-spacing:0.1em;line-height:1.9;margin-top:36px;}
.closing{text-align:center;padding:60px 0;}
.closing-quote{font-family:'IM Fell English',serif;font-style:italic;font-size:19px;color:var(--ink);line-height:1.8;max-width:520px;margin:0 auto 40px;}